import React, { useCallback, useRef, useState } from 'react';
import { ContextType, HostEvent } from '@thoughtspot/visual-embed-sdk';
import { LiveboardEmbed, SearchEmbed, SpotterEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_LIVEBOARD_ID, THOUGHTSPOT_MODEL_ID, DATABOT_ICON_URL, VIEWPORT_LESS_TOP_HEADER } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

type TabId = 'dashboard' | 'dataBot' | 'explore';

const PRIMARY = '#5B21B6';
const LABEL_PURPLE = '#2c313c';

function TabCard({
  active,
  title,
  subtitle,
  onClick,
}: {
  active: boolean;
  title: string;
  subtitle: string;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        flex: 1,
        textAlign: 'left',
        padding: '1.25rem 1.35rem',
        borderRadius: 12,
        border: active ? `1px solid ${PRIMARY}` : '1px solid #E5E7EB',
        backgroundColor: active ? PRIMARY : '#ffffff',
        color: active ? '#ffffff' : LABEL_PURPLE,
        cursor: 'pointer',
        transition: 'background-color 0.15s ease, border-color 0.15s ease',
      }}
    >
      <div style={{ fontWeight: 700, fontSize: 16, marginBottom: 4 }}>{title}</div>
      <div
        style={{
          fontSize: 13,
          fontWeight: 400,
          color: active ? 'rgba(255,255,255,0.85)' : '#6B7280',
        }}
      >
        {subtitle}
      </div>
    </button>
  );
}

function DataBotUpgrade({ onUpgrade }: { onUpgrade: () => void }) {
  return (
    <div
      style={{
        backgroundColor: '#fff',
        borderRadius: 12,
        border: '1px solid #E5E7EB',
        padding: '3rem 2rem',
        textAlign: 'center',
        maxWidth: 480,
        margin: '2rem auto',
      }}
    >
      <h2 style={{ fontSize: 20, fontWeight: 700, color: LABEL_PURPLE, margin: '0 0 8px' }}>Data Bot</h2>
      <p style={{ fontSize: 14, color: '#6B7280', lineHeight: 1.6, margin: '0 0 1.25rem' }}>
        Ask questions in plain English against your worksheet. Upgrade to Pro to enable Data Bot and related AI
        actions in the embed.
      </p>
      <button
        type="button"
        onClick={onUpgrade}
        style={{
          backgroundColor: PRIMARY,
          color: '#fff',
          border: 'none',
          padding: '10px 28px',
          borderRadius: 8,
          fontSize: 14,
          fontWeight: 600,
          cursor: 'pointer',
        }}
      >
        Upgrade to Pro
      </button>
    </div>
  );
}

export default function Analytics() {
  const [tab, setTab] = useState<TabId>('dashboard');
  const { hiddenActions, disabledActions, spotterEnabled, setTier } = useTier();
  const liveboardRef = useRef<any>(null);
  const spotterRef = useRef<any>(null);
  const searchRef = useRef<any>(null);

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    console.error('[ThoughtSpot Analytics]', formatThoughtSpotEmbedError(err), err);
  }, []);

  const handleRefresh = () => {
    try {
      if (tab === 'dashboard') liveboardRef.current?.trigger(HostEvent.Reload);
      else if (tab === 'dataBot') spotterRef.current?.trigger(HostEvent.Reload);
      else searchRef.current?.trigger(HostEvent.Reload);
    } catch (e) {
      console.warn('Reload trigger', e);
    }
  };

  const handleEditDashboard = () => {
    try {
      liveboardRef.current?.trigger(HostEvent.Edit, {}, ContextType.Liveboard);
    } catch (e) {
      console.warn('Edit trigger', e);
    }
  };

  const section =
    tab === 'dashboard'
      ? { title: 'Dashboard', subtitle: 'View and work with your saved dashboard.' }
      : tab === 'dataBot'
        ? { title: 'Data Bot', subtitle: 'Ask questions in plain English against your dataset.' }
        : { title: 'Explore', subtitle: 'Build your own analysis from the worksheet.' };

  return (
    <div
      style={{
        height: VIEWPORT_LESS_TOP_HEADER,
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: '#F9FAFB',
        overflow: 'hidden',
        minHeight: 0,
      }}
    >
      <div style={{ padding: '1.25rem 2.5rem 0', flexShrink: 0 }}>
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', flexWrap: 'wrap', gap: 16 }}>
          <div>
            <div
              style={{
                fontSize: 10,
                fontWeight: 700,
                letterSpacing: '0.12em',
                color: '#9CA3AF',
                textTransform: 'uppercase',
                marginBottom: 6,
              }}
            >
              RedFlagAlert
            </div>
            <h1 style={{ fontSize: 28, fontWeight: 700, color: PRIMARY, margin: 0 }}>Analytics</h1>
            <p style={{ fontSize: 14, color: '#6B7280', margin: '8px 0 0', maxWidth: 520 }}>
              View, explore and interrogate your analytics in one place.
            </p>
          </div>
          <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
            <button
              type="button"
              onClick={handleRefresh}
              style={{
                padding: '9px 18px',
                borderRadius: 8,
                border: '1px solid #D1D5DB',
                background: '#fff',
                color: '#374151',
                fontSize: 14,
                fontWeight: 500,
                cursor: 'pointer',
              }}
            >
              Refresh
            </button>
            {tab === 'dashboard' && (
              <button
                type="button"
                onClick={handleEditDashboard}
                style={{
                  padding: '9px 18px',
                  borderRadius: 8,
                  border: 'none',
                  background: PRIMARY,
                  color: '#fff',
                  fontSize: 14,
                  fontWeight: 600,
                  cursor: 'pointer',
                }}
              >
                Edit Dashboard
              </button>
            )}
          </div>
        </div>

        <div style={{ display: 'flex', gap: 14, marginTop: '1rem', marginBottom: '0.25rem', flexWrap: 'wrap' }}>
          <TabCard
            active={tab === 'dashboard'}
            title="Dashboard"
            subtitle="Saved dashboard"
            onClick={() => { setTab('dashboard'); }}
          />
          <TabCard
            active={tab === 'dataBot'}
            title="Data Bot"
            subtitle="Ask questions in plain English"
            onClick={() => { setTab('dataBot'); setEmbedError(null); }}
          />
          <TabCard
            active={tab === 'explore'}
            title="Explore"
            subtitle="Build your own analysis"
            onClick={() => { setTab('explore'); setEmbedError(null); }}
          />
        </div>
      </div>

      <div
        style={{
          padding: '0.75rem 2.5rem 1rem',
          flex: 1,
          minHeight: 0,
          display: 'flex',
          flexDirection: 'column',
        }}
      >
        <h2 style={{ fontSize: 18, fontWeight: 700, color: LABEL_PURPLE, margin: '0 0 4px', flexShrink: 0 }}>{section.title}</h2>
        <p style={{ fontSize: 14, color: '#6B7280', margin: '0 0 0.75rem', flexShrink: 0 }}>{section.subtitle}</p>

        {embedError && (
          <div
            role="alert"
            style={{
              marginBottom: '0.75rem',
              padding: '0.75rem 1rem',
              background: '#FEF2F2',
              border: '1px solid #FECACA',
              borderRadius: 8,
              fontSize: 13,
              color: '#991B1B',
              lineHeight: 1.5,
              flexShrink: 0,
            }}
          >
            <strong>Embed error:</strong> {embedError}
          </div>
        )}

        {tab === 'dataBot' && !spotterEnabled ? (
          <DataBotUpgrade onUpgrade={() => setTier('Pro')} />
        ) : (
          <div
            style={{
              flex: 1,
              minHeight: 0,
              backgroundColor: '#ffffff',
              borderRadius: 12,
              border: '1px solid #E5E7EB',
              overflow: 'hidden',
              display: 'flex',
              flexDirection: 'column',
            }}
          >
            {tab === 'dashboard' && (
              <LiveboardEmbed
                ref={liveboardRef}
                liveboardId={THOUGHTSPOT_LIVEBOARD_ID}
                fullHeight
                hiddenActions={hiddenActions}
                disabledActions={disabledActions}
                onError={onError}
                isLiveboardStylingAndGroupingEnabled
                additionalFlags={{ enable2ColumnLayout: true }}
                style={{ width: '100%', height: '100%', flex: 1, minHeight: 0, border: 'none' }}
              />
            )}
            {tab === 'dataBot' && spotterEnabled && (
              <SpotterEmbed
                ref={spotterRef}
                worksheetId={THOUGHTSPOT_MODEL_ID}
                onError={onError}
                hideSampleQuestions
                customizations={{ iconSpriteUrl: DATABOT_ICON_URL }}
                style={{ width: '100%', height: '100%', flex: 1, minHeight: 0, border: 'none' }}
              />
            )}
            {tab === 'explore' && (
              <SearchEmbed
                ref={searchRef}
                dataSource={THOUGHTSPOT_MODEL_ID}
                hiddenActions={hiddenActions}
                disabledActions={disabledActions}
                onError={onError}
                style={{ width: '100%', height: '100%', flex: 1, minHeight: 0, border: 'none' }}
              />
            )}
          </div>
        )}
      </div>
    </div>
  );
}
